add_action( 'template_redirect', 'perfectpixel_disable_search_404', 1 );

function perfectpixel_disable_search_query( $query ) {
	if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
		return;
	}
	$query->is_search       = false;
	$query->query_vars['s'] = '';
	$query->set( 'perfectpixel_search_disabled', 1 );
}

// WP::handle_404() skips the status header when the query is already a 404, so set both here.
function perfectpixel_disable_search_404() {
	if ( get_query_var( 'perfectpixel_search_disabled' ) ) {
		global $wp_query;
		$wp_query->set_404();
		status_header( 404 );
		nocache_headers();
	}
}

function perfectpixel_disable_search_widget() {
	unregister_widget( 'WP_Widget_Search' );
}
